import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.ChlVJx0I.js";const h=JSON.parse('{"title":"Package toggles write packages-array filters, not resource-array patterns","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0029-package-toggles-write-packages-array-filters.md","filePath":"adr/0029-package-toggles-write-packages-array-filters.md","lastUpdated":1790702633000}'),o={name:"adr/0029-package-toggles-write-packages-array-filters.md"};function i(n,e,c,l,p,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="package-toggles-write-packages-array-filters-not-resource-array-patterns" tabindex="-1">Package toggles write packages-array filters, not resource-array patterns <a class="header-anchor" href="#package-toggles-write-packages-array-filters-not-resource-array-patterns" aria-label="Permalink to &quot;Package toggles write packages-array filters, not resource-array patterns&quot;">​</a></h1><p>ADR 0012 sends every toggle into the settings resource arrays as override patterns. For a package-bundled resource that write is a no-op: pi applies resource-array patterns only to top-level resources and loads package resources from the package manifest alone, so a <code>-</code> pattern for a bundled extension reported a successful disable while the extension kept running. Its footer kept painting, and the list derived from the patterns showed the resource disabled. We decided: for a package resource, the toggle writes pi&#39;s own package filter - the packages entry becomes object form carrying a per-resource-type pattern array relative to the package root, exactly the write <code>pi config</code> performs - and the settings resource arrays carry no package-relative pattern. The top-level behavior of ADR 0012 is unchanged.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Packages-array filter (chosen).</strong> pi&#39;s native mechanism for the case: <code>pi config</code> writes it, the package manager applies it during resolution, and the patterns stay relative to the package root, so the settings file remains portable. It keeps ADR 0012&#39;s interchangeability promise intact for package resources instead of breaking it.</li><li><strong>Resource-array pattern (the old write).</strong> pi ignores it for package files. A write that reports a disable that never happens is worse than no write.</li><li><strong>User-scope shadow entry.</strong> A plain absolute path plus a <code>-</code> pattern in a settings resource array re-registers the package file at user scope, which beats the package entry in pi&#39;s precedence dedupe; verified to disable. Rejected because it puts machine-specific absolute paths into the settings and diverges from the write <code>pi config</code> makes, so the two tools would no longer agree about the file.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The toggle&#39;s settings state grows the packages array beside the four resource arrays, and its state machine must mirror <code>pi config</code>&#39;s write, including collapsing an emptied filter back to the plain string entry.</li><li>A project-scope package filter replaces, not merges, the global packages entry for the same package identity: pi&#39;s dedupe keeps the winning entry whole.</li><li>The old no-op pattern is not state. The next toggle of the resource migrates the intent into the filter and removes the pattern from the resource array, so a settings file harmed by the old write heals itself.</li></ul>',6)])])}const u=a(o,[["render",i]]);export{h as __pageData,u as default};
